Producer (Pseudocode)
do {
   // produce an item
   wait(empty)       // free slot? if not, wait
   wait(mutex)       // lock the buffer
       // add the item to the buffer
   signal(mutex)     // leave critical section
   signal(full)      // indicate one more filled slot
} while (true)
Pseudocode

Consumer (Pseudocode)
do {
   wait(full)        // item ready? if not, wait
   wait(mutex)       // lock the buffer
       // remove an item from the buffer
   signal(mutex)     // leave critical section
   signal(empty)     // indicate one more free slot
   // consume the item
} while (true)
Pseudocode

Barber (Pseudocode):
do {
   wait(customers)      // sleep until a customer arrives
   wait(mutex)          // lock the waiting-room count
   waiting = waiting - 1 // one customer leaves the queue
   signal(barber)       // barber is ready
   signal(mutex)        // unlock
   // ---- CUT HAIR ----
} while (true)
Pseudocode

Customer (Pseudocode):
wait(mutex)              // lock the waiting-room count
if (waiting < chairs) {
   waiting = waiting + 1 // take a waiting chair
   signal(customers)    // wake the barber
   signal(mutex)        // unlock
   wait(barber)         // wait until the barber is ready
   // ---- GET HAIRCUT ----
} else {
   signal(mutex)        // room full — leave
}
Pseudocode

Writer (Pseudocode):
do {
   wait(rw_mutex)         // request exclusive access
       // ---- WRITING ----
   signal(rw_mutex)       // release access
} while (true)
Pseudocode

Reader (Pseudocode):
do {
   wait(mutex)
   read_count = read_count + 1
   if (read_count == 1)
       wait(rw_mutex)     // first reader blocks writers
   signal(mutex)
       // ---- READING ----
   wait(mutex)
   read_count = read_count - 1
   if (read_count == 0)
       signal(rw_mutex)   // last reader allows writers
   signal(mutex)
} while (true)
Pseudocode

